def bidi(p):
    p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    pPr = p._p.get_or_add_pPr()
    node = pPr.find(qn('w:bidi'))
    if node is None:
        node = OxmlElement('w:bidi')
        pPr.append(node)
    node.set(qn('w:val'), '1')


def style_font(style, size, bold=False):
    style.font.name = 'B Zar'
    style.font.size = Pt(size)
    style.font.bold = bold
    style.font.color.rgb = RGBColor(24, 37, 49)
    rPr = style.element.get_or_add_rPr()
    rf = rPr.find(qn('w:rFonts'))
    if rf is None:
        rf = OxmlElement('w:rFonts')
        rPr.insert(0, rf)
    rf.set(qn('w:ascii'), 'Times New Roman')
    rf.set(qn('w:hAnsi'), 'Times New Roman')
    rf.set(qn('w:cs'), 'B Zar')


LATIN = re.compile(r'[A-Za-z][A-Za-z0-9_.:@/\-]*|\[[0-9، ]+\]')


def text_runs(p, s, size=14, bold=False):
    pos = 0
    for match in LATIN.finditer(s):
        if match.start() > pos:
            r = p.add_run(s[pos:match.start()])
            r.font.name = 'B Zar'; r.font.size = Pt(size); r.bold = bold
            r._element.get_or_add_rPr().append(OxmlElement('w:rtl'))
        r = p.add_run(match.group())
        r.font.name = 'Times New Roman'; r.font.size = Pt(size - 2); r.bold = bold
        pos = match.end()
    if pos < len(s):
        r = p.add_run(s[pos:])
        r.font.name = 'B Zar'; r.font.size = Pt(size); r.bold = bold
        r._element.get_or_add_rPr().append(OxmlElement('w:rtl'))


def add_para(doc, s, style='Normal', size=14, bold=False):
    p = doc.add_paragraph(style=style)
    bidi(p)
    text_runs(p, s, size=size, bold=bold)
    return p


def fa(n):
    return str(n).translate(str.maketrans('0123456789', '۰۱۲۳۴۵۶۷۸۹'))


def build():
    doc = Document()
    sec = doc.sections[0]
    sec.page_width = Cm(21); sec.page_height = Cm(29.7)
    sec.top_margin = Cm(2.3); sec.bottom_margin = Cm(2.2)
    sec.left_margin = Cm(2.3); sec.right_margin = Cm(2.5)
    sty = doc.styles['Normal']; style_font(sty, 14)
    sty.paragraph_format.line_spacing = 1.18
    sty.paragraph_format.space_after = Pt(6)
    title = doc.styles['Title']; style_font(title, 20, True)
    title.paragraph_format.space_after = Pt(10)
    title_ppr = title.element.get_or_add_pPr()
    title_border = title_ppr.find(qn('w:pBdr'))
    if title_border is not None:
        title_ppr.remove(title_border)
    title_border = OxmlElement('w:pBdr')
    bottom_border = OxmlElement('w:bottom')
    bottom_border.set(qn('w:val'), 'nil')
    title_border.append(bottom_border)
    title_ppr.append(title_border)
    h = doc.styles['Heading 1']; style_font(h, 16, True)
    h.paragraph_format.space_before = Pt(15)
    h.paragraph_format.space_after = Pt(5)
    h.paragraph_format.keep_with_next = True
    if 'Evidence' not in doc.styles:
        e = doc.styles.add_style('Evidence', WD_STYLE_TYPE.PARAGRAPH)
    else:
        e = doc.styles['Evidence']
    style_font(e, 11)
    e.paragraph_format.space_after = Pt(4)

    p = doc.add_paragraph(style='Title'); bidi(p); text_runs(p, 'متن گفتاری ارائه دفاع پروژه کارشناسی', 20, True)
    add_para(doc, 'راهنمای اسلایدبه‌اسلاید برای ارائهٔ حدود ۲۵ تا ۳۰ دقیقه‌ای', size=14)
    add_para(doc, 'این متن بر اساس نسخهٔ فعلی ۳۱ اسلایدی ارائه، نسخهٔ نهایی پایان‌نامه و کدهای ساخت داده و اجرای هشتم نوشته شده است. بند «پشتوانه» زیر هر اسلاید برای مرور شخصی است و قرار نیست در جلسه خوانده شود. هنگام تمرین، به نمودار یا تصویر اشاره کنید و متن را با لحن طبیعی خودتان بگویید؛ مکث‌های کوتاه و جابه‌جایی اسلایدها در زمان کل لحاظ شده‌اند.', size=13)
    spoken_words = sum(len(re.findall(r'\S+', x[3])) for x in SLIDES[:-1])
    nominal_seconds = sum(x[2] for x in SLIDES)
    add_para(doc, f'زمان پیشنهادی متن اصلی: {fa(nominal_seconds // 60)} دقیقه و {fa(nominal_seconds % 60)} ثانیه؛ زمان واقعی با اشاره به شکل‌ها و مکث‌های طبیعی حدود ۲۵ تا ۳۰ دقیقه. شمار واژه‌های گفتاری: حدود {fa(spoken_words)}.', size=12)

    for n, heading, seconds, spoken, evidence in SLIDES:
        head = f'اسلاید {fa(n)}  {heading}'
        if seconds:
            head += f'  |  حدود {fa(seconds)} ثانیه'
        else:
            head += '  |  پس از پایان ارائه'
        p = doc.add_paragraph(style='Heading 1'); bidi(p); text_runs(p, head, 16, True)
        add_para(doc, spoken)
        add_para(doc, 'پشتوانه برای مرور: ' + evidence, style='Evidence', size=11)

    p = doc.add_paragraph(style='Heading 1'); bidi(p); text_runs(p, 'نکات ضروری برای پاسخ به داور', 16, True)
    notes = [
        'عدد ۰٫۸۷۴ نتیجهٔ mAP@0.5 روی آزمونِ ساخته‌شده در این پروژه است؛ آستانهٔ اطمینان ۰٫۴۰۶ فقط نقطهٔ کاری ماتریس درهم‌ریختگی است.',
        'بهبود اجرای هشتم نسبت به هفتم به بستهٔ AdamW، نرخ اولیهٔ ۰٫۰۰۱ و زمان‌بند کسینوسی مربوط است؛ آزمایش، اثر مستقل هر جزء را اندازه نگرفت.',
        'نتیجهٔ رسمی، بهترین وزن مرحلهٔ اصلی اجرای هشتم است؛ ده دورهٔ تکمیلی با SGD و بدون موزاییک و MixUp اجرا شد، ولی برگزیده نشد.',
        'برچسب‌های آزمون رسمی IADD در نسخهٔ دانلودشده موجود نبودند. آزمون پروژه از تصاویر برچسب‌دار اولیه، با جداسازی ویدیوها، ساخته شد؛ بنابراین مقایسهٔ مستقیم عدد ما با نتیجهٔ مقالهٔ IADD منصفانه نیست.',
        'عدد کم ارزیابیِ هر ویدیو فقط نامزد بازبینی می‌ساخت. حذف دو ویدیوی معیوب پس از دیدن تصویر و برچسب‌ها انجام شد؛ ویدیوهای دشوارِ سالم حفظ شدند. محل کدهای اصلی در بخش «پشتوانه» اسلایدهای مربوط آمده است.',
    ]
    for item in notes:
        p = doc.add_paragraph(style='Normal'); bidi(p)
        p.style = 'Normal'; p.paragraph_format.left_indent = Cm(0.2)
        text_runs(p, '• ' + item, 13)

    footer = sec.footer.paragraphs[0]
    bidi(footer)
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    text_runs(footer, 'متن ارائهٔ دفاع  |  صفحه ', 10)
    field = OxmlElement('w:fldSimple'); field.set(qn('w:instr'), 'PAGE')
    footer._p.append(field)

    OUT.parent.mkdir(parents=True, exist_ok=True)
    doc.save(OUT)
    print(f'OUT={OUT}')
    print(f'WORDS={spoken_words} NOMINAL_SECONDS={nominal_seconds}')


if __name__ == '__main__':
    build()
